function e(string $x): string {return htmlspecialchars($x, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');}
function site_url(string $path=''): string {return '/'.ltrim($path, '/');}
function icon_svg(string $name='arrow'): string {
  $path = match ($name) {
    'arrow'=>'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    'upright'=>'<path d="M7 17 17 7M8 7h9v9"/>',
    'menu'=>'<path d="M4 7h16M4 12h16M4 17h16"/>',
    'close'=>'<path d="M6 6l12 12M18 6 6 18"/>',
    'check'=>'<path d="m5 12 5 5L20 7"/>',
    'lock'=>'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    'spark'=>'<path d="m12 2 2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2L12 2Z"/>',
    default=>'<circle cx="12" cy="12" r="9"/>'
  };
  return '<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'.$path.'</svg>';
}
function section_label(string $text): string {return '<div class="eyebrow"><span class="eyebrow-square"></span>'.e($text).'</div>';}
function action_link(string $text, string $url, string $class='btn btn-dark'): string {return '<a class="'.e($class).'" href="'.e($url).'">'.e($text).'<span class="btn-arrow">'.icon_svg('upright').'</span></a>';}
function service_card(array $s, int $i): string {
  $colors=['violet','peach','mint','blue']; $color=$colors[$i%count($colors)];
  return '<article class="service-card card-'.e($color).' reveal"><div class="service-top"><span class="service-num">'.e($s[0]).'</span><span class="service-symbol">'.icon_svg('upright').'</span></div><div><h3>'.e($s[1]).'</h3><p>'.e($s[2]).'</p></div><a class="stretched-link" href="/contact/?service='.rawurlencode($s[3]).'" aria-label="Enquire About '.e($s[1]).'"></a></article>';
}
function journal_card(array $post): string {
 return '<a class="journal-card reveal" href="/journal/'.e($post['slug']).'/"><div class="journal-art art-'.e($post['theme']).'"><span class="art-star">✳</span><span class="art-word">Ideas<br>Worth<br>Sharing<span class="art-dot">.</span></span><span class="art-squiggle">↗</span></div><div class="journal-meta"><span>'.e($post['tag']).'</span><span>'.e($post['date']).'</span></div><h3>'.e($post['title']).'</h3><div class="journal-read">Explore The Story '.icon_svg('arrow').'</div></a>';
}
function posted_articles(): array {
  $items=(defined('STATIC_PREVIEW') && STATIC_PREVIEW) ? sample_posts() : [];
  if(defined('STATIC_PREVIEW') && STATIC_PREVIEW) return $items;
  try {
    if (function_exists('db')) {
      $pdo=db();
      $q=$pdo->query("SELECT slug, category AS tag, DATE_FORMAT(published_at,'%e %M %Y') AS date, title, excerpt, 'blue' AS theme FROM posts WHERE status='published' ORDER BY published_at DESC LIMIT 30");
      foreach($q->fetchAll(PDO::FETCH_ASSOC) as $p) $items[]=$p;
    }
  }catch(Throwable $ignored){};
  return $items;
}
function article_for_slug(string $slug): ?array {
 if(defined('STATIC_PREVIEW') && STATIC_PREVIEW){foreach(sample_posts() as $post)if($post['slug']===$slug)return $post;return null;}
 try{if(function_exists('db')){
 $q=db()->prepare("SELECT slug,category AS tag,DATE_FORMAT(published_at,'%e %M %Y') AS date,title,excerpt,seo_title,seo_description,ai_summary,body,'blue' AS theme FROM posts WHERE slug=? AND status='published' LIMIT 1"); $q->execute([$slug]);$post=$q->fetch(PDO::FETCH_ASSOC);return $post?:null;
 }}catch(Throwable $ignored){} return null;
}
function render_site(string $page='home', ?string $slug=null): string {
  $preview=defined('STATIC_PREVIEW') && STATIC_PREVIEW;
  $allowed=['home','about','services','contact','journal','article','portal','privacy','admin','404'];
  if(!in_array($page,$allowed,true))$page='404';
  $foundArticle=$page==='article' ? article_for_slug((string)$slug) : null;
  if($page==='article' && !$foundArticle)$page='404';
  [$title,$description]=page_seo($page,$slug);
  if($foundArticle){$title=($foundArticle['seo_title']??$foundArticle['title']).' | '.BUSINESS_NAME;$description=($foundArticle['seo_description']??null)?:$foundArticle['excerpt'];}
  $base=rtrim(getenv('SITE_URL') ?: BUSINESS_URL,'/');
  $canonical=$base.($page==='home'?'/':($page==='article'?'/journal/'.rawurlencode((string)$slug).'/':'/'.$page.'/'));
  $noindex=$preview || in_array($page,['portal','admin','404'],true);
  $token=(!$preview && function_exists('csrf_token')) ? csrf_token() : 'preview';
  ob_start();
?>
